# Paper 6: 2601_00285v1 - SkelGS
# ============================================================
t6 = []
t6.append("SkelGS旨在从稀疏时序观测（每个时间步仅单张标定图像）重建关节式动态目标。方法假设可获取目标骨骼结构作为输入：骨骼S=(J,E)，其中J={j_1,...,j_K}∈R^{K×3}为3D关节点位置集，E为父子连接边集。骨骼可通过人工标注或现成姿态估计方法获得。")
t6.append("静态3D Gaussians初始化。首先构建目标的初始静态3DGS重建。采用标准3DGS管道：G={G_i|(μ_i,q_i,s_i,α_i,c_i^sh)}，其中μ_i为中心位置，q_i为表示旋转的四元数，s_i为缩放向量，α_i为不透明度，c_i^sh为球谐系数。给定相机姿态，通过沿视线方向的alpha混合渲染像素颜色：C=Σ_k c_k·α'_k·Π_{j<k}(1-α'_j)。静态3DGS可通过多视图图像优化获得，也可通过预训练图像到3D扩散模型生成。")
t6.append("骨骼驱动的变形场。在静态3DGS和标注骨骼图基础上，学习一个变形场将初始Gaussians变换到各稀疏时间步的观测图像。学习到的变形应受输入骨骼约束同时保持对稀疏观测的拟合灵活性。受可学习LBS（线性混合蒙皮）技术启发，采用MLP建模每个关节的时间相关局部旋转和根关节的局部平移：")
t6.append("(r_k(t),t_root(t))=MLP_pose(γ(t))，其中r_k∈R^4为局部旋转四元数（仅对根关节预测额外平移t_root），γ(t)为时间的位置编码。给定骨骼图中的父子层次结构，通过前向运动学计算各关节的全局变换：T_k(t)=FK(T_k(t),T_parent(k)(t),r_k(t),t_root(t))，其中T_k=(R_k,t_k)为关节k在时间t的全局旋转和平移。")
t6.append("精细蒙皮运动场。构建骨骼后（每根骨骼对应连接关节j_k和其父关节的边缘），规范空间中每个Gaussian中心μ_i通过可学习蒙皮权重变换到时间t：μ_i(t)=Σ_{b∈B}w_{i,b}·(R_b(t)·μ_i+t_b(t))，R_i(t)=Σ_{b∈B}w_{i,b}·R_b(t)（旋转的加权近似）。蒙皮权重w_{i,b}满足Σ_b w_{i,b}=1。")
t6.append("蒙皮权重计算：由于输入骨骼可能含噪声且缺乏蒙皮和变形信息，将每根骨骼的蒙皮效果建模为规范空间中的RBF（径向基函数）核：w~_{i,b}=exp(-d(μ_i,b)^2/σ_b^2)，其中d(μ_i,b)为Gaussian中心到骨骼b在规范帧中的距离，σ_b为每根骨骼的可学习影响半径。同时为补偿骨骼噪声，学习位置相关修正场Δw_i=MLP_corr(γ(μ_i))，最终归一化权重w_{i,b}=Softmax(log(w~_{i,b})+Δw_{i,b})。")
t6.append("细节变形场。上述骨骼驱动变形捕获了由关节变换传播到Gaussians的粗粒度关节运动，但稀疏骨骼无法考虑细粒度非刚性变形。引入额外的姿态相关细节变形场：Δμ_i(t)=MLP_detail(γ(μ_i),{R_k(t)})，考虑规范帧中的Gaussian中心和该时间步预测的关节姿态。最终Gaussian中心为μ_i'(t)=μ_i(t)+Δμ_i(t)。")
t6.append("训练目标与正则化。变形场的可训练参数包括关节局部姿态预测器MLP_pose、骨骼影响半径{σ_b}、蒙皮修正场MLP_corr和细节变形场MLP_detail。静态规范Gaussians参数保持不变。总损失L=L_render+λ_smooth·L_smooth+λ_detail·L_detail。")
t6.append("L_render遵循3DGS的感知损失（L1+λ·L_D-SSIM），强制变形后的Gaussians从对应视点渲染时匹配观测图像。L_smooth=Σ_k‖∇^2_t r_k(t)‖^2对预测的局部关节旋转施加时间拉普拉斯平滑，缓解单视图监督下自遮挡导致的模糊性，防止突变姿态变化。L_detail=Σ_i‖Δμ_i(t)‖^2对细节变形偏移施加L2正则化，因为该场仅用于建模小幅局部调整而非大位移。")
t6.append("连续运动插值。由于仅在少数离散时间步监督，学习到的θ_deform在查询未见时间步时可能产生时序不一致的运动。为解决此问题，变形场设计使得仅局部姿态预测显式依赖时间t，从而允许对关节姿态在未见中间时间步进行有效插值，同时保持蒙皮修正场和细节变形场的效果。")
output['2601_00285v1'] = {'technical': '\n\n'.join(t6)}

