# Paper 7: 2601_01577v1 - HanoiWorld
# ============================================================
t7 = []
t7.append("HanoiWorld将自主驾驶建模为确定性马尔可夫决策过程(MDP)，同时引入内部连续随机状态和确定性状态，在有限时域环境中输出确定性连续动作。MDP定义为(S,A,P,R,γ)，其中S为连续状态空间，A为连续动作空间（自车加速度和转向角），P为包含随机状态（捕获环境随机性模式）和确定性状态（由循环规划器产生历史上下文）的状态转移动力学，R为奖励函数，γ=0.997为折扣因子（直接采用DreamerV3设置）。")
t7.append("系统架构包含四个核心模块。(1)环境接口：基于HighwayEnv构建，供智能体交互。(2)转移队列(Transition Queue)：大小有限的体验收集器，存储有效轨迹片段（长度≥阈值L_min），包含BEV(Bird-Eye-View)RGB图像和交互元数据（智能体动作、自车动作、奖励值）。(3)世界模型(World Model)：以编码器-RSSM为核心，提供想象嵌入作为Actor-Critic控制器的训练信号。(4)Actor-Critic控制器：在潜在空间中输出动作，形成闭环交互循环直至智能体达到终止状态。")
t7.append("V-JEPA 2编码器（核心创新）。HanoiWorld的主要创新是采用基于自监督学习的强预训练图像编码器V-JEPA 2。与传统DreamerV3编码器需要重建像素（引入噪声和随机性）不同，V-JEPA 2学习环境交互的本质知识（运动、物体移动），已通过超过100万小时视频的自监督预训练。编码器采用Student-Teacher双分支架构和EMA稳定训练以防止表示坍塌：θ_teacher←τ·θ_teacher+(1-τ)·θ_student，τ=0.996。")
t7.append("给定视频V和通过移除时空patch子集得到的掩码视图V_masked，学生编码器从可见token提取表示z_vis=f_student(V_masked)。预测器g_pred被训练预测teacher编码器对被掩码token的表示z_target=f_teacher(V)[masked_positions]。训练目标为L1损失：L=‖g_pred(z_vis, M)-sg(z_target)‖_1，仅应用于被掩码的patch。通过迫使编码器猜测被掩码的patch内容，创造了防止表示坍塌的挑战，使得在没有完整环境几何结构的情况下也能学习和预测语义占据信息。")
t7.append("RSSM（循环状态空间模型）。遵循DreamerV3架构，RSSM作为内部记忆模块，存储长期历史语义的确定性记忆h_t和基于环境编码信号的随机潜在值z_t（用于捕捉世界演化的不确定性）。世界动力学生成过程：h_t=f_RNN(h_{t-1},z_{t-1},a_{t-1})（确定性转移），z_t~p(z_t|h_t)（随机先验），而给定实际观测时的后验为z_t~q(z_t|h_t,e_t)，其中e_t=encoder(o_t)为编码器嵌入。")
t7.append("HanoiWorld还包含延续预测器p(continue_t|h_t,z_t)~Bernoulli，预测轨迹片段是否延续。延续预测器的训练方式与原DreamerV3一致，使用二元交叉熵作为logistic回归目标。")
t7.append("Actor-Critic框架。从DreamerV3的奖励-价值学习范式直接推导，策略网络π(a_t|h_t,z_t)和价值网络v(h_t,z_t)均定义在RSSM产生的潜在状态上，而非实际环境状态。这使Actor-Critic完全在学习的潜在环境中运行。Actor通过最大化λ-回报的期望学习动作选择，Critic通过最小化价值预测与λ-回报之间的TD误差学习评估状态价值。")
t7.append("训练目标与算法。HanoiWorld的训练仅模拟DreamerV3的动力学和Actor-Critic训练过程，不进行编码器的重建训练。编码器微调阶段（Bottleneck和空间预测器训练）：除了L1损失外，还采用Variance-Invariance-Covariance正则化。具体包括：(1)方差正则化——约束teacher瓶颈输出的各维度方差接近1，防止坍塌；(2)协方差正则化——约束teacher瓶颈输出各维度间协方差接近0，促进特征去相关。总Bottleneck损失L_bottleneck=λ_1·L_L1+λ_2·L_var+λ_3·L_cov，权重设为(1.0,1.0,0.1)以确保稳定性和防止坍塌。")
t7.append("编码器在预处理自NuScenes数据集的2D BEV图像上微调，这些BEV图像通过LiDAR点云渲染并附加障碍物和环境运动元数据生成，使V-JEPA 2编码器可直接处理。RSSM模块训练采用三项损失：(1)预测损失——对观测转移概率、奖励函数和延续标志的负对数似然求和；(2)动力学损失——最小化实际后验分布与世界模型从先验潜在记忆想象的先验分布之间的KL散度；(3)表示损失——锚定编码器不偏离潜在世界模型期望。此损失配置遵循DreamerV3的权重设计。")
